def transform(grid):
    n = len(grid[0])
    center = n // 2
    out = [[0] * n for _ in range(n)]
    # Expand the central 2 into a downward-opening V.
    for r in range(center + 1):
        out[r][center - r] = 2
        out[r][center + r] = 2
    # Continue the diagonal lattice, confined to the expanding V above its apex.
    for r in range(3, n):
        left = max(0, center - r) if r <= center else 0
        right = min(n - 1, center + r) if r <= center else n - 1
        for c in range(left, right + 1):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
